function deepening(profile:EditorialProfile,index:number,kind:LearningBlockKind,locale:Locale):string[]{
  const notes=profile.notes[locale],a=notes[(index*2)%notes.length],b=notes[(index*2+1)%notes.length],c=notes[(index*2+2)%notes.length]
  const stage=profile.stages[locale][index%profile.stages[locale].length],nextStage=profile.stages[locale][(index+1)%profile.stages[locale].length]
  const variable=profile.control.label[locale],low=profile.control.low[locale],high=profile.control.high[locale],mode=studyMode[kind]
  const copy={
    en:{sequence:[`Read “${stage}” as a threshold rather than a date on a diagram. Put this proposition beside it: ${a} Now identify what material is present, what can still be reversed, and which measurement would justify moving toward “${nextStage}”. The transition matters because timing changes the same action.`,`Build a before-and-after record for this transition. Before “${stage}”, predict one physical, chemical or sensory observation from this evidence: ${b} After the transition, test the prediction against this boundary condition: ${c} If both observations remain unchanged, the proposed mechanism needs revision rather than a more confident story.`],variable:[`Treat “${variable}” as the only moving control. Establish the lower condition—${low}—and the higher condition—${high}—while keeping sample, glass, timing and order stable. Use this mechanism to predict direction, not a guaranteed flavour: ${a} Record a null result with the same care as a dramatic contrast.`,`Repeat the comparison in alternating order and explain the result with two pieces of evidence. First test this observable claim: ${b} Then challenge it with this limitation: ${c} A useful conclusion states the direction of change, the conditions held constant and the uncertainty that remains after repetition.`],diagnosis:[`Open the case at “${stage}” with two rival explanations. Use this first proposition as evidence, not as a verdict: ${a} Ask which observation would separate the hypotheses most efficiently, then reveal only that observation. Avoid choosing a place, fault or method merely because one memorable descriptor fits.`,`Construct the disconfirmation test from these two statements. Supporting evidence: ${b} Boundary or competing explanation: ${c} Check a clean comparison, timing, another sample and process history where relevant. Finish with a confidence level and name the result that would force you to change the diagnosis.`],transfer:[`Turn “${stage}” into a table protocol. State the question before pouring, use small equal samples, keep one control stable and ask every participant to write an observation before discussion. Anchor the practical prediction in this mechanism: ${a} The aim is a repeatable comparison, not agreement by authority.`,`After the first pass, change only “${variable}” from ${low} toward ${high}. Retaste in reverse order and connect the change to this evidence: ${b} Then test the limit expressed here: ${c} End by choosing one real action for service, cellaring, pairing or the next bottle.`],evidence:[`Slow down at “${stage}” and separate three layers: what is directly visible or measurable, what mechanism could explain it, and what remains inference. Begin from this claim: ${a} Rewrite it as an observation that another learner could verify without knowing the module title, then name the instrument, reference or comparison needed.`,`Place these statements side by side rather than blending them. Evidence to test: ${b} Limit or context to preserve: ${c} Trace each technical or legal term to the cited source, note its jurisdiction or experimental conditions, and keep sensory probability separate from deterministic flavour claims.`]},
    de:{sequence:[`Lies „${stage}“ als Schwelle und nicht als Datum in einem Diagramm. Stelle diese Aussage daneben: ${a} Bestimme dann vorhandenes Material, noch umkehrbare Schritte und den Messwert, der den Übergang zu „${nextStage}“ rechtfertigt. Timing zählt, weil dieselbe Handlung je nach Phase anders wirkt.`,`Baue für den Übergang ein Vorher-nachher-Protokoll. Sage vor „${stage}“ eine physikalische, chemische oder sensorische Beobachtung aus dieser Evidenz voraus: ${b} Prüfe danach die Vorhersage gegen diese Randbedingung: ${c} Bleibt beides unverändert, braucht der Mechanismus Revision statt eine selbstsicherere Geschichte.`],variable:[`Behandle „${variable}“ als einzige bewegte Kontrolle. Setze die niedrige Bedingung – ${low} – und die hohe – ${high} –, während Probe, Glas, Zeit und Reihenfolge stabil bleiben. Sage mit diesem Mechanismus eine Richtung statt eines garantierten Aromas voraus: ${a} Notiere auch ein Nullergebnis sorgfältig.`,`Wiederhole den Vergleich in wechselnder Reihenfolge und erkläre das Ergebnis mit zwei Evidenzen. Prüfe zuerst diese beobachtbare Aussage: ${b} Fordere sie anschließend mit dieser Grenze heraus: ${c} Ein belastbarer Schluss nennt Änderungsrichtung, Konstanten und die nach Wiederholung verbleibende Unsicherheit.`],diagnosis:[`Öffne den Fall bei „${stage}“ mit zwei konkurrierenden Erklärungen. Nutze diese Aussage als Evidenz, nicht als Urteil: ${a} Frage, welche Beobachtung die Hypothesen am besten trennt, und decke nur sie auf. Herkunft, Fehler oder Methode folgen nie aus einem einzigen einprägsamen Deskriptor.`,`Baue den Widerlegungstest aus zwei Aussagen. Stützende Evidenz: ${b} Grenze oder Alternative: ${c} Prüfe je nach Fall Vergleichsglas, Zeit, zweite Probe und Prozesshistorie. Beende mit einem Vertrauensgrad und nenne das Ergebnis, das die Diagnose ändern würde.`],transfer:[`Mache aus „${stage}“ ein Tischprotokoll. Stelle die Frage vor dem Einschenken, nutze kleine gleiche Proben, halte eine Kontrolle stabil und lasse alle vor der Diskussion eine Beobachtung notieren. Verankere die Vorhersage in diesem Mechanismus: ${a} Ziel ist Wiederholbarkeit, nicht Einigkeit durch Autorität.`,`Verändere nach dem ersten Durchgang nur „${variable}“ von ${low} in Richtung ${high}. Koste in umgekehrter Reihenfolge und verbinde die Änderung mit dieser Evidenz: ${b} Prüfe dann die hier genannte Grenze: ${c} Beende mit einer realen Handlung für Service, Lagerung, Pairing oder die nächste Flasche.`],evidence:[`Verlangsame bei „${stage}“ und trenne drei Ebenen: direkt sichtbar oder messbar, möglicher Mechanismus und verbleibende Deutung. Beginne mit dieser Aussage: ${a} Formuliere daraus eine Beobachtung, die jemand ohne Kenntnis des Modultitels prüfen kann, und nenne Instrument, Referenz oder Vergleich.`,`Stelle diese Aussagen nebeneinander, statt sie zu vermischen. Zu prüfende Evidenz: ${b} Zu erhaltende Grenze oder Kontext: ${c} Verfolge technische oder rechtliche Begriffe bis zur Quelle, notiere Rechtsraum oder Versuchsbedingungen und trenne sensorische Wahrscheinlichkeit von deterministischen Aromaversprechen.`]},
    fr:{sequence:[`Lisez « ${stage} » comme un seuil, non une date sur un schéma. Placez cette proposition à côté : ${a} Identifiez la matière présente, ce qui reste réversible et la mesure justifiant le passage vers « ${nextStage} ». Le moment compte car une même action change d’effet selon la phase.`,`Construisez un relevé avant-après. Avant « ${stage} », prédisez une observation physique, chimique ou sensorielle à partir de cet indice : ${b} Après le seuil, testez-la contre cette limite : ${c} Si rien ne change, révisez le mécanisme au lieu de renforcer le récit.`],variable:[`Traitez « ${variable} » comme seul contrôle mobile. Fixez la condition basse — ${low} — puis haute — ${high} — en gardant échantillon, verre, durée et ordre stables. À partir de ce mécanisme, prédisez une direction, pas un arôme garanti : ${a} Consignez aussi soigneusement un résultat nul.`,`Répétez en ordre alterné et expliquez avec deux indices. Testez d’abord cette affirmation observable : ${b} Confrontez-la ensuite à cette limite : ${c} Une conclusion utile donne le sens du changement, les constantes et l’incertitude qui demeure après répétition.`],diagnosis:[`Ouvrez le cas à « ${stage} » avec deux explications rivales. Utilisez cette proposition comme indice, non verdict : ${a} Cherchez l’observation qui les sépare le mieux puis ne révélez qu’elle. Ne concluez jamais lieu, défaut ou méthode d’un seul descripteur mémorable.`,`Construisez le test de réfutation avec deux énoncés. Indice favorable : ${b} Limite ou alternative : ${c} Contrôlez verre témoin, temps, autre échantillon et historique si pertinent. Terminez par un niveau de confiance et le résultat qui ferait changer le diagnostic.`],transfer:[`Transformez « ${stage} » en protocole de table. Posez la question avant de servir, utilisez de petites doses égales, gardez un contrôle stable et faites écrire une observation avant discussion. Ancrez la prédiction dans ce mécanisme : ${a} Le but est la répétabilité, non l’accord d’autorité.`,`Après le premier passage, ne changez que « ${variable} » de ${low} vers ${high}. Regoûtez en ordre inverse et reliez le changement à cet indice : ${b} Testez ensuite cette limite : ${c} Finissez par une action réelle de service, garde, accord ou prochain vin.`],evidence:[`À « ${stage} », séparez trois niveaux : visible ou mesurable, mécanisme possible et inférence restante. Partez de cette affirmation : ${a} Réécrivez-la comme une observation vérifiable sans connaître le titre, puis nommez instrument, référence ou comparaison nécessaire.`,`Placez les énoncés côte à côte. Indice à tester : ${b} Limite ou contexte à préserver : ${c} Remontez chaque terme technique ou légal à la source, notez juridiction ou conditions expérimentales et séparez probabilité sensorielle de toute promesse déterministe.`]},
    es:{sequence:[`Lee «${stage}» como umbral, no como fecha en un diagrama. Coloca al lado esta proposición: ${a} Identifica la materia presente, qué sigue siendo reversible y qué medida justificaría pasar hacia «${nextStage}». El momento importa porque una misma acción cambia de efecto según la fase.`,`Construye un registro antes-después. Antes de «${stage}», predice una observación física, química o sensorial desde esta evidencia: ${b} Después del umbral, contrástala con este límite: ${c} Si nada cambia, revisa el mecanismo en lugar de reforzar la historia.`],variable:[`Trata «${variable}» como único control móvil. Fija la condición baja —${low}— y la alta —${high}— manteniendo muestra, copa, tiempo y orden. Predice una dirección, no un aroma garantizado, desde este mecanismo: ${a} Registra con igual cuidado un resultado nulo.`,`Repite en orden alterno y explica con dos evidencias. Prueba primero esta afirmación observable: ${b} Después desafíala con este límite: ${c} Una conclusión útil declara dirección del cambio, constantes y la incertidumbre que queda tras repetir.`],diagnosis:[`Abre el caso en «${stage}» con dos explicaciones rivales. Usa esta proposición como evidencia, no como veredicto: ${a} Busca la observación que mejor las separa y revela solo esa. Nunca concluyas lugar, defecto o método por un único descriptor memorable.`,`Construye la prueba de refutación con dos enunciados. Evidencia favorable: ${b} Límite o alternativa: ${c} Comprueba copa limpia, tiempo, otra muestra e historial cuando proceda. Termina con nivel de confianza y el resultado que te obligaría a cambiar el diagnóstico.`],transfer:[`Convierte «${stage}» en protocolo de mesa. Formula la pregunta antes de servir, usa muestras pequeñas iguales, conserva un control estable y pide una observación escrita antes de hablar. Ancla la predicción en este mecanismo: ${a} El objetivo es repetir, no acordar por autoridad.`,`Tras la primera pasada, cambia solo «${variable}» de ${low} hacia ${high}. Prueba en orden inverso y conecta el cambio con esta evidencia: ${b} Después examina este límite: ${c} Termina eligiendo una acción real de servicio, guarda, maridaje o siguiente botella.`],evidence:[`En «${stage}» separa tres niveles: visible o medible, mecanismo posible e inferencia restante. Parte de esta afirmación: ${a} Reescríbela como observación verificable sin conocer el título y nombra instrumento, referencia o comparación necesarios.`,`Coloca ambos enunciados lado a lado. Evidencia a probar: ${b} Límite o contexto que conservar: ${c} Lleva cada término técnico o legal hasta la fuente, anota jurisdicción o condiciones experimentales y separa probabilidad sensorial de promesas deterministas.`]}
  } as const
  return [...copy[locale][mode]].map(text=>text.replace(/Reg.oûtez/,'Regoûtez'))
}
function bodyFor(profile:EditorialProfile,index:number,kind:LearningBlockKind):Localized<string[]>{
  return Object.fromEntries(locales.map(locale=>{
    const notes=profile.notes[locale]
    return [locale,[notes[(index*2)%notes.length],notes[(index*2+1)%notes.length],notes[(index*2+2)%notes.length],...deepening(profile,index,kind,locale)]]
  })) as Localized<string[]>
}
function makeBlock(profile:EditorialProfile,index:number,kind:LearningBlockKind):LearningBlock{
  const labels=blockLabels[kind]
  const options=kind==='knowledge-check'?Object.fromEntries(locales.map(locale=>[locale,[profile.notes[locale][5],profile.notes[locale][1],profile.notes[locale][6]]])) as Localized<string[]>:undefined
  const states=Object.fromEntries(locales.map(locale=>[locale,[profile.notes[locale][4],profile.notes[locale][0],profile.notes[locale][2]]])) as Localized<string[]>
  return {id:`${profile.id}--${kind}-${index}`,kind,title:labels.title,eyebrow:labels.eyebrow,body:bodyFor(profile,index,kind),duration:kind==='sources'?3:kind==='knowledge-check'?4:6,behavior:kind==='decision-case'?'host-reveal':kind==='sources'?'self-paced':'host-or-self',linkedEntityIds:profile.entities,
    media:mediaKinds.includes(kind)?{src:profile.media[index%2],alt:l(`Evidence illustration for ${profile.title.en}`,`Evidenzillustration zu ${profile.title.de}`,`Illustration d’indices pour ${profile.title.fr}`,`Ilustración de evidencias para ${profile.title.es}`),focus:profile.archetype}:undefined,
    options,answer:kind==='knowledge-check'?1:undefined,stages:profile.stages,control:{...profile.control,states},sources:kind==='sources'?profile.sources:undefined}
}
function makeModule(profile:EditorialProfile):LearningModule{
  const kinds:LearningBlockKind[]=[...patterns[profile.archetype],'glossary','entity-connections','sources']
  return {id:profile.id,school:profile.school,title:profile.title,question:profile.question,summary:Object.fromEntries(locales.map(locale=>[locale,profile.notes[locale][0]])) as Localized<string>,level:profile.level,minutes:48,archetype:profile.archetype,
    outcomes:Object.fromEntries(locales.map(locale=>[locale,profile.notes[locale].slice(1,4)])) as Localized<string[]>,experiment:Object.fromEntries(locales.map(locale=>[locale,profile.notes[locale][4]])) as Localized<string>,blocks:kinds.map((kind,index)=>makeBlock(profile,index,kind)),entityIds:profile.entities}
}

export const learningModules:LearningModule[]=profiles.map(makeModule)
export const learningModuleById=(id:string)=>learningModules.find(module=>module.id===id)
export const learningBlockById=(id:string)=>learningModules.flatMap(module=>module.blocks.map(block=>({module,block}))).find(item=>item.block.id===id)
export const curriculumSources:Record<LearningSchool,{label:string;url:string}[]>=Object.fromEntries(Object.keys(schoolCopy).map(school=>[school,profiles.filter(profile=>profile.school===school).flatMap(profile=>profile.sources.map(({label,url})=>({label,url})))])) as Record<LearningSchool,{label:string;url:string}[]>

function words(value:string){return value.match(/[\p{L}\p{N}]+(?:[-’'][\p{L}\p{N}]+)*/gu)?.length??0}
function trigrams(value:string){const tokens=(value.toLocaleLowerCase().match(/[\p{L}\p{N}]+/gu)??[]);return new Set(tokens.slice(0,-2).map((token,index)=>`${token} ${tokens[index+1]} ${tokens[index+2]}`))}
function similarity(a:Set<string>,b:Set<string>){let common=0;for(const value of a)if(b.has(value))common++;return common/Math.max(1,a.size+b.size-common)}
export function learningValidation(){
  const issues:string[]=[],ids=new Set<string>(),blockIds=new Set<string>()
  for(const module of learningModules){
    if(ids.has(module.id))issues.push(`duplicate module ${module.id}`);ids.add(module.id)
    if(new Set(module.blocks.flatMap(block=>block.media?.src?[block.media.src]:[])).size<2)issues.push(`${module.id} needs two distinct visuals`)
    for(const locale of locales){const segments=[module.title[locale],module.question[locale],module.summary[locale],module.experiment[locale],...module.outcomes[locale],...module.blocks.flatMap(block=>[block.title[locale],...block.body[locale],...(block.options?.[locale]??[]),...(block.stages?.[locale]??[]),...(block.sources??[]).map(item=>item.supports[locale])])];const text=[...new Set(segments.map(segment=>segment.trim()).filter(Boolean))].join(' ');if(words(text)<800)issues.push(`${module.id} ${locale} has ${words(text)} unique authored words; minimum 800`)}
    for(const block of module.blocks){if(blockIds.has(block.id))issues.push(`duplicate block ${block.id}`);blockIds.add(block.id)}
  }
  for(const locale of locales)for(let i=0;i<learningModules.length;i++)for(let j=i+1;j<learningModules.length;j++){
    const text=(module:LearningModule)=>module.blocks.flatMap(block=>block.body[locale]).join(' '),score=similarity(trigrams(text(learningModules[i])),trigrams(text(learningModules[j])))
    if(score>.34)issues.push(`content similarity ${locale} ${learningModules[i].id}/${learningModules[j].id}: ${score.toFixed(2)}`)
  }
  return {modules:learningModules.length,schools:new Set(learningModules.map(module=>module.school)).size,archetypes:new Set(learningModules.map(module=>module.archetype)).size,issues}
}
